import inspect

import pytest

import invoices.pricing as pricing


def test_line_total_example_1():
    assert pricing.line_total(2, 5.0) == 10.0

def test_line_total_example_2():
    assert pricing.line_total(3, 2.5, tax_percent=8) == 8.1

def test_line_total_example_3():
    with pytest.raises(ValueError):
        pricing.line_total(-1, 5.0)

def test_line_total_signature():
    assert callable(pricing.line_total)
    assert list(inspect.signature(pricing.line_total).parameters) == ['quantity', 'unit_price', 'tax_percent']

def test_subtotal_example_1():
    assert pricing.subtotal([(2, 5.0), (1, 2.5)]) == 12.5

def test_subtotal_example_2():
    assert pricing.subtotal([(2, 5.0)], tax_percent=10) == 11.0

def test_subtotal_signature():
    assert callable(pricing.subtotal)
    assert list(inspect.signature(pricing.subtotal).parameters) == ['items', 'tax_percent']

